export class CerebralComponent {
  _cdr: any
  _app: any
  props: any
  view: any
  onUpdate: any

  constructor(cdr: any, app: any) {
    if (!cdr || typeof cdr.detectChanges !== 'function') {
      throw new Error(
        'You did not pass a "ChangeDetectorRef" to the Cerebral Component parent class'
      )
    }
    if (!app || typeof app.flush !== 'function') {
      throw new Error(
        'You did not pass a "AppService" to the Cerebral Component parent class'
      )
    }
    this._cdr = cdr
    this._app = app
  }

  ngOnInit() {}
  ngOnDestroy() {}
  ngAfterViewInit() {}
  ngOnChanges() {}
}
